            modelBuilder.Entity<DichVuPhatSinh>().Property(p => p.DonGia).HasPrecision(18, 2);
            modelBuilder.Entity<LoaiPhong>().Property(p => p.GiaThamKhao).HasPrecision(18, 2);
            modelBuilder.Entity<Phong>().Property(p => p.DienTich).HasPrecision(18, 2);
            modelBuilder.Entity<Phong>().Property(p => p.GiaMotDem).HasPrecision(18, 2);

            // Cấu hình mở rộng độ dài chuỗi cho DatPhong và KhachHang để đáp ứng dữ liệu tiếng Việt
            modelBuilder.Entity<DatPhong>(entity =>
            {
                entity.Property(e => e.TrangThai).HasMaxLength(50);
                entity.Property(e => e.GhiChuLeTan).HasMaxLength(255);
                entity.Property(e => e.YeuCauDacBiet).HasMaxLength(255);
            });

            modelBuilder.Entity<KhachHang>(entity =>
            {
                entity.Property(e => e.HoTen).HasMaxLength(50);
                entity.Property(e => e.Email).HasMaxLength(50);
                entity.Property(e => e.DiaChi).HasMaxLength(100);
                entity.Property(e => e.SoGiayToTuyThan).HasMaxLength(30);
                entity.Property(e => e.QuocTich).HasMaxLength(20);
                entity.Property(e => e.SoDienThoai).HasMaxLength(20);
            });

